<template>
  <section id="trader-discussion" class="trader-council">
    <div class="council-heading"><h3>Trader discussion</h3><span>{{ activeCount }} participating<span v-if="inactive.length"> · {{ inactive.length }} unavailable</span></span></div>
    <p class="council-note">{{ run.council_version===2 ? 'Read each trader’s question and the other trader’s reply below. Directional lean and entry readiness are separate.' : 'Earlier report: three initial opinions and a moderator review; no challenge/reply rounds were run.' }}</p>
    <div v-if="latestViews.length" class="stance-board"><div v-for="group in stanceGroups" :key="group.id" :class="group.id"><strong>{{ group.members.length }}</strong><span>{{ group.label }}</span><p>{{ group.members.map(item=>item.name).join(' · ') || 'No views recorded' }}</p></div></div>
    <p v-if="latestViews.length" class="view-note">{{ changedCount }} traders changed their directional view. These counts describe the discussion, not a win probability.</p>
    <details v-if="run.roster?.length" class="roster"><summary>Who participates and why</summary><div v-for="role in run.roster" :key="role.id" class="roster-row"><div><strong>{{ role.name }}</strong><p>{{ role.active ? role.focus : role.inactive_reason }}</p></div><span>{{ role.active ? 'Participating' : 'No data' }}</span></div></details>
    <div class="round-tabs" role="group" aria-label="Discussion rounds"><button :class="{selected:tab==='opening'}" @click="tab='opening'">Opening views <span>{{ run.opinions?.length || 0 }}</span></button><button v-if="run.council_version===2" :class="{selected:tab==='challenges'}" @click="tab='challenges'">Challenges <span>{{ run.challenges?.length || 0 }}</span></button><button v-if="run.council_version===2" :class="{selected:tab==='replies'}" @click="tab='replies'">Replies <span>{{ run.replies?.length || 0 }}</span></button></div>
    <template v-if="tab==='opening'"><details v-for="opinion in run.opinions || []" :key="opinion.id" class="opinion"><summary><strong>{{ opinion.name }}</strong><span>{{ stance(opinion.stance) }}</span></summary><p v-if="opinion.setup_status" class="readiness">Entry: {{ readiness(opinion.setup_status) }}</p><p>{{ opinion.thesis }}</p><ul><li v-for="reason in opinion.reasons" :key="reason">{{ reason }}</li></ul><p><strong>Opposing case:</strong> {{ opinion.counterargument }}</p><p><strong>Invalidation:</strong> {{ opinion.invalidation }}</p></details><p v-if="!run.opinions?.length" class="pending">Opening views have not been recorded yet.</p></template>
    <template v-if="tab==='challenges'"><article v-for="challenge in run.challenges || []" :key="challenge.id" class="exchange"><div class="speaker"><strong>{{ challenge.name }}</strong><span>challenges {{ challenge.target_name }}</span></div><details v-if="challenge.target_thesis" class="target-view"><summary>View the argument being challenged · {{ stance(challenge.target_stance) }}</summary><p>{{ challenge.target_thesis }}</p></details><p class="question">{{ challenge.question }}</p><p class="why">{{ challenge.why_it_matters }}</p><div v-if="replyFor(challenge)" class="reply"><strong>{{ replyFor(challenge).name }} replies</strong><p>{{ replyFor(challenge).response }}</p><span>{{ replyFor(challenge).changed_stance ? 'View changed' : 'View retained' }} · {{ stance(replyFor(challenge).stance) }}</span></div><p v-else class="pending">{{ run.status==='running' ? 'Awaiting this specialist’s reply.' : 'No reply was recorded in this run.' }}</p></article><p v-if="!run.challenges?.length" class="pending">Cross-examination follows the independent opening views.</p></template>
    <template v-if="tab==='replies'"><article v-for="reply in run.replies || []" :key="reply.id" class="exchange"><div class="speaker"><strong>{{ reply.name }}</strong><span>responds to {{ reply.responding_to_name }}</span></div><p>{{ reply.response }}</p><div class="revision"><span>{{ stance(reply.initial_stance) }}</span><span aria-hidden="true">→</span><strong>{{ stance(reply.stance) }}</strong><small>{{ reply.changed_stance ? 'Changed' : 'Retained' }}</small></div><p><strong>Current thesis:</strong> {{ reply.revised_thesis }}</p><p class="why">{{ reply.change_reason }}</p><p><strong>Still unresolved:</strong> {{ reply.remaining_disagreement }}</p></article><p v-if="!run.replies?.length" class="pending">Replies are generated after the specialists have received their actual challenges.</p></template>
    <div v-if="run.verdict?.discussion?.length" class="moderator"><h4>Moderator’s synthesis</h4><p v-for="(item,index) in run.verdict.discussion" :key="index">{{ item }}</p></div>
  </section>
</template>

<script setup>
import { computed, ref, watch } from 'vue'
const props=defineProps({run:{type:Object,required:true}})
const tab=ref(props.run.challenges?.length ? 'challenges' : 'opening')
watch(()=>props.run.challenges?.length,(count,previous)=>{if(count && !previous)tab.value='challenges'})
const activeCount=computed(()=>props.run.roster?.filter(x=>x.active).length||props.run.opinions?.length||0)
const inactive=computed(()=>props.run.roster?.filter(x=>!x.active)||[])
const stance=s=>({bullish:'Bullish',bearish:'Bearish',mixed:'Mixed',no_setup:'No clear setup'}[s]||s)
const readiness=s=>({conditional:'Conditional setup; trigger required',wait:'Waiting for a defined trigger',insufficient_data:'More data needed'}[s]||s)
const latestViews=computed(()=>(props.run.opinions||[]).map(view=>props.run.replies?.find(reply=>reply.id===view.id)||view))
const stanceGroups=computed(()=>[{id:'bullish',label:'Bullish lean'},{id:'bearish',label:'Bearish lean'},{id:'mixed',label:'Mixed / undecided'},{id:'no_setup',label:'Abstaining'}].map(group=>({...group,members:latestViews.value.filter(view=>view.stance===group.id)})))
const changedCount=computed(()=>props.run.replies?.filter(reply=>reply.changed_stance).length||0)
const replyFor=challenge=>props.run.replies?.find(reply=>reply.id===challenge.target_id)
</script>

<style scoped>
.target-view{font-size:11px;color:#888;margin:12px 0}.target-view summary{cursor:pointer;color:#777}.target-view p{font-size:12px;color:#666;border-left:2px solid #ddd;padding-left:12px;margin-top:10px}

.stance-board{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));border-left:1px solid #ddd;border-top:1px solid #ddd;margin-top:18px}.stance-board>div{border-bottom:1px solid #ddd;border-right:1px solid #ddd;padding:14px;min-width:0}.stance-board strong{font-size:25px;font-weight:500;display:inline-block;margin-right:10px}.stance-board .bearish strong{color:#aa3c32}.stance-board .bullish strong{color:#2c7655}.stance-board span{font-size:12px}.stance-board p{font-size:10px;color:#888;margin:5px 0 0}.view-note,.readiness{font-size:11px;color:#888;margin:12px 0}.readiness{color:#805e42}.exchange .reply{border-radius:0 8px 8px 0}.exchange .speaker span{color:#7a6260}
.trader-council{border-top:1px solid #ddd;margin-top:26px;padding-top:25px;color:#222;font:13px/1.7 'Helvetica Neue',Helvetica,Arial,sans-serif}.council-heading{display:flex;align-items:baseline;justify-content:space-between;gap:15px}.council-heading h3{font-size:18px;font-weight:500;margin:0}.council-heading>span{color:#888;font-size:10px;text-align:right}.council-note,.pending{font-size:12px;color:#808088;line-height:1.7;margin:12px 0 20px}.roster{font-size:12px;margin:20px 0}.roster summary{cursor:pointer;color:#444}.roster-row{display:flex;justify-content:space-between;gap:20px;padding:12px 0;border-bottom:1px solid #eee}.roster-row strong{font-size:12px;font-weight:500}.roster-row p{color:#888;font-size:11px;margin-top:5px}.roster-row>span{font-size:10px;color:#888;white-space:nowrap}.round-tabs{display:flex;gap:0;border-bottom:1px solid #ccc;margin:20px 0 0;overflow-x:auto}.round-tabs button{background:white;border:0;border-bottom:2px solid transparent;padding:12px 10px;color:#888;font:12px inherit;font-family:inherit;cursor:pointer;white-space:nowrap;min-height:45px}.round-tabs button.selected{border-bottom-color:#ff4f00;color:#111}.round-tabs button span{font-size:10px;margin-left:6px;color:#aaa}.round-tabs button:focus-visible,.opinion summary:focus-visible{outline:3px solid #ff4f00;outline-offset:2px}.opinion{padding:16px 0;border-bottom:1px solid #ddd;color:#666}.opinion summary{cursor:pointer;display:flex;justify-content:space-between;gap:12px;list-style:none}.opinion summary:after{content:'+';color:#aaa}.opinion[open] summary:after{content:'−'}.opinion summary strong{font-weight:500;color:#222;flex:1}.opinion summary span{font-size:11px;color:#888}.opinion p{margin-top:14px}.opinion ul{padding-left:18px}.opinion li{margin:7px 0}.exchange{padding:22px 0;border-bottom:1px solid #ddd}.speaker strong{font-size:14px;font-weight:600;display:block}.speaker span{color:#999;font-size:11px}.exchange>p{margin-top:12px;color:#666;font-size:13px}.exchange .question{color:#222;font-size:14px}.exchange .why{color:#888;font-size:12px}.reply{border-left:2px solid #ff4f00;background:#f7f7f8;padding:14px 16px;margin-top:18px}.reply>strong{font-size:12px;font-weight:500}.reply p{font-size:13px;color:#666;margin:10px 0}.reply>span{font-size:11px;color:#888}.revision{display:flex;align-items:center;flex-wrap:wrap;gap:12px;font-size:12px;margin:18px 0}.revision>span{color:#888}.revision>small{color:#b53e13;font-size:10px;border:1px solid #e5c7bb;padding:2px 6px}.moderator{padding:24px 0}.moderator h4{font-size:15px;font-weight:600}.moderator p{font-size:13px;color:#666;margin:13px 0}.trader-council p{overflow-wrap:anywhere}@media(max-width:520px){.council-heading{flex-direction:column;gap:5px}.round-tabs button{padding:12px 8px;font-size:11px}.roster-row{gap:12px}.opinion summary{gap:8px}.opinion summary strong{font-size:12px}.opinion summary span{font-size:10px}}
</style>
